'use client';
import { useEffect,useState } from 'react';import Link from 'next/link';import { money, products, whatsappNumber } from '@/lib/products';
export function CartClient(){const[items,setItems]=useState<string[]>([]);useEffect(()=>setItems(JSON.parse(localStorage.getItem('cart')||'[]')),[]);const list=items.map(s=>products.find(p=>p.slug===s)).filter(Boolean) as typeof products;const total=list.reduce((a,p)=>a+p.price,0);const remove=(i:number)=>{const next=items.filter((_,idx)=>idx!==i);setItems(next);localStorage.setItem('cart',JSON.stringify(next))};const msg=`Olá! Vim pelo site da Dubai Essence e tenho interesse nos perfumes: ${list.map(p=>p.name).join(', ')}. Total estimado: ${money(total)}`;return <div className="grid gap-8 lg:grid-cols-[1fr_360px]"><div className="space-y-4">{list.length===0?<div className="lux-card rounded-[2rem] p-8"><p>Sua sacola está vazia.</p><Link className="mt-4 inline-block text-oldgold" href="/loja">Ver perfumes →</Link></div>:list.map((p,i)=><div className="lux-card flex items-center justify-between rounded-[2rem] p-5" key={i}><div><h2 className="font-serif text-2xl">{p.name}</h2><p className="text-coffee/60">{p.brand} • {p.volume}</p><p className="font-bold text-oldgold">{money(p.price)}</p></div><button onClick={()=>remove(i)} className="rounded-full border border-gold/30 px-4 py-2">Remover</button></div>)}</div><aside className="lux-card h-fit rounded-[2rem] p-6"><h2 className="font-serif text-3xl">Resumo</h2><p className="mt-4 flex justify-between"><span>Itens</span><b>{list.length}</b></p><p className="mt-2 flex justify-between text-lg"><span>Total</span><b>{money(total)}</b></p><a className={`btn-gold mt-6 block rounded-full px-6 py-4 text-center ${!list.length?'pointer-events-none opacity-50':''}`} href={`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(msg)}`} target="_blank">Finalizar pelo WhatsApp</a><Link className="mt-3 block text-center text-sm text-oldgold" href="/checkout">Ir para checkout</Link></aside></div>}
